import random
import string

class Virus:
    def __init__(self, length=100):
        self.genome = ''.join(random.choices(string.ascii_letters + string.digits, k=length))

    def mutate(self):
        index = random.randrange(len(self.genome))
        self.genome = self.genome[:index] + random.choice(string.ascii_letters + string.digits) + self.genome[index + 1:]

    def fitness(self, anti_virus):
        return anti_virus(self.genome)

class AntiVirus:
    def __init__(self, signatures):
        self.signatures = signatures

    def detect(self, genome):
        return any(signature in genome for signature in self.signatures)

def genetic_algorithm(anti_virus, population_size=100, generations=1000):
    population = [Virus() for _ in range(population_size)]

    for _ in range(generations):
        population = sorted(population, key=lambda v: anti_virus.fitness(v.genome), reverse=True)

        if anti_virus.detect(population[0].genome):
            break

        next_generation = population[:10]
        while len(next_generation) < population_size:
            parent1, parent2 = random.choices(population[:50], k=2)
            child = Virus()
            child.genome = parent1.genome[:len(parent1.genome)//2] + parent2.genome[len(parent2.genome)//2:]
            child.mutate()
            next_generation.append(child)

        population = next_generation

    return population[0]

if __name__ == "__main__":
    signatures = ['ABCD1234', 'EFGH5678', 'IJKL9012']
    anti_virus = AntiVirus(signatures)
    virus = genetic_algorithm(anti_virus)

    print(f"Generated Virus Genome: {virus.genome}")
